//! Local owner settings for the observe-only native Windows sampler.
use serde::{Deserialize,Serialize};use serde_json::{Value,json};
use std::{path::{Path,PathBuf},process::{Command,Stdio},io::Read,time::{Duration,Instant},sync::{Mutex,OnceLock}};
static APPLY:OnceLock<Mutex<()>>=OnceLock::new();
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="PascalCase",deny_unknown_fields)]
pub(crate) struct Disk{drive:String,enabled:bool,free_percent:f64}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="PascalCase",deny_unknown_fields)]
pub(crate) struct Config{schema_version:u32,enabled:bool,sample_seconds:u32,available_memory_percent:f64,commit_percent:f64,repeat_minutes:u32,disks:Vec<Disk>,#[serde(default,rename="LegacyDiskFreeGiB")]legacy_disk_free_gi_b:Option<f64>}
fn script()->Result<PathBuf,String>{let p=std::env::current_exe().map_err(|_|"RESOURCE_MONITOR_UNAVAILABLE")?.parent().ok_or("RESOURCE_MONITOR_UNAVAILABLE")?.join("resource-monitor/ResourceMonitor.ps1");if p.is_file(){return Ok(p)}#[cfg(debug_assertions)]{let p=Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().join("tools/resource-monitor/ResourceMonitor.ps1");if p.is_file(){return Ok(p)}}Err("RESOURCE_MONITOR_NOT_PACKAGED".into())}
fn shell()->PathBuf{let ps=PathBuf::from(r"C:\Program Files\PowerShell\7\pwsh.exe");if ps.is_file(){ps}else{PathBuf::from(std::env::var_os("SystemRoot").unwrap_or_else(||r"C:\Windows".into())).join("System32/WindowsPowerShell/v1.0/powershell.exe")}}
// A timed-out settings write remains uncertain and keeps running under its lock.
// Killing it could interrupt the sampler replacement before rollback/receipt.
fn run_apply(parameters:&[String])->Result<(),String>{let mut command=Command::new(shell());command.args(parameters).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null());#[cfg(windows)]{use std::os::windows::process::CommandExt;command.creation_flags(0x08000000);}let mut child=command.spawn().map_err(|_|"RESOURCE_MONITOR_UNAVAILABLE")?;let start=Instant::now();loop{match child.try_wait(){Ok(Some(status))=>return if status.success(){Ok(())}else{Err("RESOURCE_MONITOR_COMMAND_FAILED".into())},Ok(None)if start.elapsed()<Duration::from_secs(30)=>std::thread::sleep(Duration::from_millis(100)),_=>return Err("RESOURCE_MONITOR_APPLY_UNCONFIRMED".into())}}}
fn run(args:&[String])->Result<String,String>{let mut command=Command::new(shell());command.args(args).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::null());#[cfg(windows)]{use std::os::windows::process::CommandExt;command.creation_flags(0x08000000);}let mut child=command.spawn().map_err(|_|"RESOURCE_MONITOR_UNAVAILABLE")?;let stdout=child.stdout.take().ok_or("RESOURCE_MONITOR_UNAVAILABLE")?;let reader=std::thread::spawn(move||{let mut bytes=Vec::new();let _=stdout.take(131072).read_to_end(&mut bytes);bytes});let start=Instant::now();loop{match child.try_wait(){Ok(Some(status))=>{let bytes=reader.join().map_err(|_|"RESOURCE_MONITOR_UNAVAILABLE")?;if !status.success(){return Err("RESOURCE_MONITOR_COMMAND_FAILED".into());}return String::from_utf8(bytes).map_err(|_|"RESOURCE_MONITOR_RESPONSE_INVALID".into());},Ok(None)if start.elapsed()<Duration::from_secs(25)=>std::thread::sleep(Duration::from_millis(50)),_=>{let _=child.kill();let _=child.wait();let _=reader.join();return Err("RESOURCE_MONITOR_READ_TIMEOUT".into());}}}}
fn args(mode:&str)->Result<Vec<String>,String>{Ok(vec!["-NoProfile".into(),"-NonInteractive".into(),"-File".into(),script()?.to_string_lossy().into(),"-Mode".into(),mode.into()])}
pub(crate) fn read()->Result<Value,String>{serde_json::from_str(&run(&args("Read")?)?).map_err(|_|"RESOURCE_MONITOR_RESPONSE_INVALID".into())}
fn validate(c:&Config)->Result<(),String>{if c.schema_version!=2||!c.available_memory_percent.is_finite()||!(1.0..=95.0).contains(&c.available_memory_percent)||!c.commit_percent.is_finite()||!(1.0..99.0).contains(&c.commit_percent)||!(60..=3600).contains(&c.sample_seconds)||!(5..=1440).contains(&c.repeat_minutes)||c.disks.len()>26{return Err("RESOURCE_MONITOR_SETTINGS_INVALID".into())}let mut seen=std::collections::HashSet::new();for d in &c.disks{if d.drive.len()!=2||!d.drive.as_bytes()[0].is_ascii_uppercase()||d.drive.as_bytes()[1]!=b':'||!seen.insert(&d.drive)||!d.free_percent.is_finite()||!(0.1..=95.0).contains(&d.free_percent){return Err("RESOURCE_MONITOR_SETTINGS_INVALID".into())}}Ok(())}
#[cfg(windows)]fn elevate(parameters:&[String])->Result<(),String>{
 use windows::{core::PCWSTR,Win32::{UI::Shell::{ShellExecuteExW,SHELLEXECUTEINFOW,SEE_MASK_NOCLOSEPROCESS},System::Threading::WaitForSingleObject,Foundation::CloseHandle}};
 fn wide(v:&str)->Vec<u16>{v.encode_utf16().chain(Some(0)).collect()}
 let exe=wide(&shell().to_string_lossy());let verb=wide("runas");let mut quoted=Vec::new();for p in parameters{if p.contains('"'){return Err("RESOURCE_MONITOR_PATH_INVALID".into())}quoted.push(format!("\"{p}\""));}let params=wide(&quoted.join(" "));
 let mut info=SHELLEXECUTEINFOW{cbSize:std::mem::size_of::<SHELLEXECUTEINFOW>()as u32,fMask:SEE_MASK_NOCLOSEPROCESS,lpVerb:PCWSTR(verb.as_ptr()),lpFile:PCWSTR(exe.as_ptr()),lpParameters:PCWSTR(params.as_ptr()),nShow:0,..Default::default()};unsafe{ShellExecuteExW(&mut info).map_err(|e|if e.code().0 as u32&0xffff==1223{"RESOURCE_MONITOR_CONSENT_CANCELLED"}else{"RESOURCE_MONITOR_ADMIN_REQUIRED"}.to_string())?;let result=WaitForSingleObject(info.hProcess,30000);let _=CloseHandle(info.hProcess);if result.0!=0{return Err("RESOURCE_MONITOR_APPLY_UNCONFIRMED".into())}}Ok(())
}
pub(crate) fn apply(config:Config)->Result<Value,String>{validate(&config)?;let _guard=APPLY.get_or_init(Mutex::default).try_lock().map_err(|_|"RESOURCE_MONITOR_BUSY")?;
 let before=read()?;for d in config.disks.iter().filter(|d|d.enabled){if !before["drives"].as_array().is_some_and(|rows|rows.iter().any(|r|r["drive"]==d.drive)){return Err("RESOURCE_MONITOR_DRIVE_UNAVAILABLE".into());}}
 let root=crate::local_safety::collector_root().ok_or("RESOURCE_MONITOR_UNAVAILABLE")?;std::fs::create_dir_all(root.join("requests")).map_err(|_|"RESOURCE_MONITOR_STORAGE_UNAVAILABLE")?;let id=uuid::Uuid::new_v4().to_string();let path=root.join("requests").join(format!("{id}.json"));let request=json!({"requestId":id,"ownerSid":before["ownerSid"],"callerPid":before["callerPid"],"callerImage":before["callerImage"],"callerCreatedUtc":before["callerCreatedUtc"],"createdUtc":time::OffsetDateTime::now_utc().format(&time::format_description::well_known::Rfc3339).map_err(|_|"RESOURCE_MONITOR_TIME_INVALID")?,"config":config});std::fs::write(&path,serde_json::to_vec(&request).map_err(|_|"RESOURCE_MONITOR_SETTINGS_INVALID")?).map_err(|_|"RESOURCE_MONITOR_STORAGE_UNAVAILABLE")?;
 let mut parameters=args("Apply")?;parameters.extend(["-RequestFile".into(),path.to_string_lossy().into()]);
 #[cfg(windows)]{if unsafe{windows::Win32::UI::Shell::IsUserAnAdmin()}.as_bool(){run_apply(&parameters)?;}else{elevate(&parameters)?;}}
 #[cfg(not(windows))]{let _=parameters;return Err("RESOURCE_MONITOR_WINDOWS_ONLY".into());}
 let result=path.with_file_name(format!("{id}.result.json"));let receipt:Value=std::fs::read(&result).ok().and_then(|b|serde_json::from_slice(&b).ok()).ok_or("RESOURCE_MONITOR_APPLY_UNCONFIRMED")?;if receipt["applied"]!=true||receipt["requestId"]!=id{return Err("RESOURCE_MONITOR_APPLY_UNCONFIRMED".into())}
 let _=std::fs::remove_file(path);let _=std::fs::remove_file(result);read()
}
#[cfg(test)]mod tests{use super::*;#[test]fn actual_powershell_config_roundtrips_legacy_gib_name(){let v=json!({"SchemaVersion":2,"Enabled":true,"SampleSeconds":120,"AvailableMemoryPercent":10,"CommitPercent":90,"RepeatMinutes":30,"Disks":[],"LegacyDiskFreeGiB":5});let c:Config=serde_json::from_value(v).unwrap();assert_eq!(c.legacy_disk_free_gi_b,Some(5.0));assert_eq!(serde_json::to_value(c).unwrap()["LegacyDiskFreeGiB"],5.0);}#[test]fn percent_config_rejects_non_drives_duplicates_and_bad_ranges(){let mut c=Config{schema_version:2,enabled:true,sample_seconds:120,available_memory_percent:10.0,commit_percent:90.0,repeat_minutes:30,disks:vec![Disk{drive:"C:".into(),enabled:true,free_percent:12.5}],legacy_disk_free_gi_b:None};assert!(validate(&c).is_ok());c.disks[0].drive="C:;command".into();assert!(validate(&c).is_err());c.disks[0].drive="C:".into();c.disks.push(c.disks[0].clone());assert!(validate(&c).is_err());c.disks.pop();c.available_memory_percent=101.0;assert!(validate(&c).is_err());}}
